// Map whatever trigger fired into { path: <Windows path for the runner>, original: <basename>, trigger: <which> }
const cfg = $('Config').first().json;
const j = $input.first().json;

let raw = null;
let trigger = 'manual';
if (j.path && typeof j.path === 'string' && !j.body) {
  raw = j.path; trigger = 'file';                 // Local File Trigger → { event, path }
} else if (j.body && j.body.path) {
  raw = j.body.path; trigger = 'webhook';         // Webhook → { body: { path } }
} else {
  raw = cfg.MANUAL_PATH; trigger = 'manual';      // Manual Trigger → Config.MANUAL_PATH
}
if (!raw) throw new Error('No input path. Set Config.MANUAL_PATH or POST {"path": ...} to the webhook.');

// Container path → Windows path for every watched folder (Inbox is consumed; Captures is read in place).
let winPath = raw;
const maps = [[cfg.CONTAINER_INBOX, cfg.INBOX], [cfg.CONTAINER_CAPTURES, cfg.CAPTURES]];
for (const [cDir, wDir] of maps) {
  const c = (cDir || '').replace(/\/+$/, '');
  if (c && wDir && raw.startsWith(c + '/')) {
    const rel = raw.slice(c.length + 1).replace(/\//g, '\\');
    winPath = wDir.replace(/\\+$/, '') + '\\' + rel;
    if (trigger === 'file') trigger = raw.startsWith((cfg.CONTAINER_CAPTURES || '\0').replace(/\/+$/, '') + '/') ? 'captures' : 'file';
    break;
  }
}
const original = winPath.split(/[\\/]/).pop();
return [{ json: { path: winPath, raw_path: raw, original, trigger } }];

// Ollama Verdict failed (runner down mid-run, Ollama off, timeout...). Keep going without the LLM.
const predict = $('Predict').first().json;
const err = $input.first().json;
const reason = (err && (err.error && (err.error.message || err.error))) || err.message || 'request failed';
const candidates = (predict.candidates || []).map(c => ({ ...c, llm: null, llm_error: String(reason) }));
return [{ json: { ok: true, candidates, recommended: predict.recommended, llm_error: String(reason) } }];

// Plain-English review message (see CONTRACT.md). One block per candidate, best first, no jargon.
const cfg = $('Config').first().json;
const ingest = $('Ingest').first().json;
const norm = $('Normalize Input').first().json;
const transcribe = $('Transcribe').first().json;
const inp = $input.first().json;
const candidates = (inp.candidates || []).slice();
const recommended = inp.recommended ?? $('Predict').first().json.recommended ?? null;
const scoreOut = $('Score').first().json || {};
const strongCount = Number(scoreOut.strong_count ?? candidates.filter(c => c.strong_moment).length);
const target = cfg.TARGET_LEN_SEC || 30;
const hours = cfg.REVIEW_TIMEOUT_HOURS || 24;

function mmss(sec) {
  sec = Math.max(0, Math.round(Number(sec) || 0));
  const h = Math.floor(sec / 3600), m = Math.floor((sec % 3600) / 60), s = sec % 60;
  return h ? `${h}:${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}` : `${m}:${String(s).padStart(2, '0')}`;
}
function r0(x) { return Math.round(Number(x) || 0); }

// Turn the scorer's signal string into something a person would say.
function whatHappens(c) {
  const s = c.signals || {};
  const bits = [];
  if (s.voice_command) bits.push(`🎤 you said "${s.voice_command.text}" at ${mmss(s.voice_command.at)} — this is the ${Math.round(c.end - c.start)} s before it`);
  if (s.v1_events > 0) bits.push(`gunfire/impact at ${mmss((s.firefight_peak_abs || c.start) - c.start)} into the clip`);
  else if (s.onsets >= 6) bits.push(`${s.onsets} bursts of game action`);
  if (s.exclaim >= 0.5) bits.push('you react loudly');
  if ((s.phrases || []).length) bits.push(`you say "${s.phrases[0]}"`);
  if (s.speech_density >= 1.5) bits.push('you talk fast the whole time');
  else if (s.speech_density > 0 && s.speech_density < 0.3) bits.push('almost no talking');
  if (!bits.length) bits.push(c.strong_moment ? 'game action' : 'talking only, no game action');
  return bits.join(', ');
}
function grade(total) {
  if (total >= 80) return 'strong';
  if (total >= 70) return 'good';
  if (total >= 50) return 'okay';
  return 'weak';
}
// Sort best-first so the top of the message is the one to look at.
candidates.sort((a, b) => r0((b.predict || {}).total) - r0((a.predict || {}).total));

const lines = [];
lines.push(`🎬 Clip review — ${norm.original || ingest.source} (${mmss(ingest.duration_sec)} long)`);
lines.push('');
if (recommended === null || strongCount === 0) {
  lines.push(strongCount === 0
    ? `⛔ Nothing worth clipping: no game action found in this recording, only talking. The ${candidates.length} windows below are listed so you can see what it looked at.`
    : `⛔ Nothing I'd recommend: the best window scored under ${inp.min_recommend ?? 70}/100. Listed in case you want one anyway.`);
} else {
  const voiced = candidates.filter(c => (c.signals || {}).voice_command).length;
  lines.push((voiced ? `🎤 You said "clip it" ${voiced} time${voiced === 1 ? '' : 's'} — ${voiced === 1 ? 'that one is' : 'those are'} listed first. ` : '') + `Found ${strongCount} moment${strongCount === 1 ? '' : 's'} with real game action. Each one is a ${target}-second clip.`);
}
if (transcribe && transcribe.words === 0) lines.push(`(No speech detected — scores are from the game audio only.)`);
lines.push('');
for (const c of candidates) {
  const p = c.predict || {};
  const total = r0(p.total);
  const star = (recommended !== null && c.rank === recommended) ? ' ⭐ BEST PICK' : '';
  lines.push(`#${c.rank}${star} — ${mmss(c.start)} to ${mmss(c.end)} — ${total}/100 (${grade(total)})`);
  lines.push(`  What happens: ${whatHappens(c)}`);
  const weak = [];
  if (r0(p.hook) < 15) weak.push('slow first 2 seconds');
  if (r0(p.retention) < 15) weak.push(`${(((p.notes || {}).retention || {}).dead_air_sec || 0).toFixed(0)}s of dead air`);
  if (((p.notes || {}).visual || {}).penalty) weak.push(p.notes.visual.penalty);
  if (!c.strong_moment) weak.push('no game action');
  lines.push(`  Weak spot: ${weak.length ? weak.join(', ') : 'none big'}${p.biggest_fix ? ' → ' + p.biggest_fix : ''}`);
  if (c.llm && c.llm.verdict) lines.push(`  Ollama says: "${c.llm.verdict}"${c.llm.agrees === false ? ' (disagrees with the score)' : ''}`);
  if (c.llm && c.llm.title) lines.push(`  Title if posted: ${c.llm.title}`);
  lines.push('');
}
lines.push('Score = how likely it holds a viewer: first 2 seconds, dead air, how clear the audio is, and Shorts length.');
lines.push(`👉 Reply with a number to make that clip (e.g. ${recommended ?? 1}). "${recommended ?? 1} start 5s earlier" or "${recommended ?? 1} end 3s later" to nudge it. "no" to skip all. If you don't answer within ${hours} h nothing is made. If more than one review is open, long-press this message → Reply, so I know which clip you mean.`);

// Telegram caps a message at 4096 chars: drop whole candidate blocks from the bottom until it fits.
let text = lines.join('\n');
const footer = lines.slice(-2).join('\n');
let shown = candidates.length;
while (text.length > 3900 && shown > 1) {
  shown -= 1;
  const head = lines.slice(0, lines.indexOf('') + 1);          // title + summary
  const blocks = [];
  let cur = [];
  for (const l of lines.slice(head.length, lines.length - 2)) { if (l === '' && cur.length) { blocks.push(cur); cur = []; } else if (l !== '') cur.push(l); }
  if (cur.length) blocks.push(cur);
  const kept = blocks.slice(0, shown).map(b => b.join('\n')).join('\n\n');
  text = head.join('\n') + kept + `\n\n(+${candidates.length - shown} more — ask for "more" or pick from these)\n\n` + footer;
}
return [{ json: {
  text,
  job_id: ingest.job_id,
  job_dir: ingest.job_dir,
  input: norm.path,
  original: norm.original,
  duration_sec: ingest.duration_sec,
  candidates: inp.candidates || [],
  recommended,
} }];

// Start the getUpdates poll loop. Carries ONLY the loop state: the review payload (candidates etc.) is
// re-read from `Build Review Message` by Parse Reply, so each poll iteration stays a few hundred bytes
// instead of re-saving the whole candidate list (a 24 h wait would otherwise grow the execution to ~10 MB).
const cfg = $('Config').first().json;
const review = $('Build Review Message').first().json;
const sent = $input.first().json || {};          // Telegram node output: { ok, result: { message_id, ... } }
const msg = sent.result || sent;
const sent_at = Math.floor(Date.now() / 1000);
const hours = Number(cfg.REVIEW_TIMEOUT_HOURS) || 24;
return [{ json: {
  phase: 'pick',
  job_id: review.job_id,
  review_message_id: msg && msg.message_id ? msg.message_id : null,
  sent_at,
  deadline: sent_at + hours * 3600,
  poll_offset: 0,
  attempts: 0,
} }];

// Look for the user's reply among the getUpdates results. Loop state comes from the last run of `Wait 70s`.
// Several reviews may be open in the same chat, so:
//   * a Telegram "reply to" (long-press → Reply) is accepted only by the review it quotes;
//   * a plain message is accepted by whichever review CLAIMS it first at the runner (/claim_reply);
//   * forwarded messages and pasted review blocks are ignored.
// We never advance Telegram's offset (always 0), so no review can make a message vanish for another one.
const cfg = $('Config').first().json;
const state = $('Wait 70s').first().json;
const resp = $input.first().json || {};
const chatId = String(cfg.TELEGRAM_CHAT_ID);
const now = Math.floor(Date.now() / 1000);

const updates = (resp.ok === true && Array.isArray(resp.result)) ? resp.result : [];
const attempts = (Number(state.attempts) || 0) + 1;
const poll_error = resp.error ? String(resp.error.message || resp.error) : (resp.ok === false ? String(resp.description || 'getUpdates not ok') : null);
const carry = { job_id: state.job_id, review_message_id: state.review_message_id, review_message_ids: state.review_message_ids || null, phase: state.phase || 'pick', ranks: state.ranks || null, sent_at: state.sent_at, deadline: state.deadline };
const looksLikeReview = t => /BEST PICK|What happens:|Weak spot:|Clip review —/.test(t);

const mine = [];
for (const u of updates) {
  const m = u.message;
  if (!m || !m.chat || String(m.chat.id) !== chatId) continue;
  if (!(Number(m.date) > Number(state.sent_at))) continue;
  if (typeof m.text !== 'string' || !m.text.trim()) continue;
  if (m.forward_origin || m.forward_date || looksLikeReview(m.text)) continue;
  const quoted = m.reply_to_message && m.reply_to_message.message_id;
  const myIds = (state.review_message_ids || [state.review_message_id]).map(String);
  if (quoted && !myIds.includes(String(quoted))) continue;   // addressed to another review
  mine.push({ u, m, addressed: !!quoted });
}
mine.sort((a, b) => Number(a.m.date) - Number(b.m.date));   // oldest first: claim in arrival order

let best = null;
for (const cand of mine) {
  if (cand.addressed) { best = cand; break; }
  try {
    const r = await this.helpers.httpRequest({ method: 'POST', url: cfg.RUNNER_URL + '/claim_reply', json: true,
      body: { update_id: cand.u.update_id, job_id: state.job_id }, timeout: 10000 });
    if (r && r.claimed) { best = cand; break; }
  } catch (e) {
    // Runner too old for /claim_reply (or down): behave like before the claim existed rather than never answering.
    if (/unknown route|404|ECONNREFUSED|claim_reply/i.test(String(e && e.message || e))) { best = cand; break; }
  }
}

if (best) {
  return [{ json: { ...carry, found: true, text: best.m.text.trim(), reply_date: best.m.date, update_id: best.u.update_id,
                    next_offset: 0, attempts, timed_out: false, poll_error: null } }];
}
return [{ json: { ...carry, found: false, next_offset: 0, attempts, timed_out: now >= Number(state.deadline), poll_error } }];

// Implements the CONTRACT.md reply grammar. One output item per pick, so "1 and 5" renders both.
const review = $('Build Review Message').first().json;
const cfg = $('Config').first().json;
const raw = String($input.first().json.text || '').trim();   // set by Find Reply
const text = raw.toLowerCase().replace(/\s+/g, ' ');
const duration = Number(review.duration_sec) || 0;

const base = { reply: raw, job_id: review.job_id, job_dir: review.job_dir, input: review.input,
               original: review.original, candidates: review.candidates };
const invalid = (error) => [{ json: { ...base, action: 'invalid', error } }];

// ---- phase 2: clips delivered, waiting for "post" / "keep"
const state = $('Wait 70s').first().json || {};
if (state.phase === 'post') {
  const delivered = $('Prepare Clip Message').all().map(it => it.json);
  if (['keep', 'no', 'skip', 'none', 'dont post', "don't post"].includes(text)) {
    return [{ json: { ...base, action: 'keep', delivered } }];
  }
  const m = text.match(/^(?:post|upload|yes|publish)(?:\s+(all|[\d\s,and+&]+))?$/);
  if (!m) return invalid(`Could not parse "${raw}" — in this step the options are "post", "post 2", "post all" or "keep"`);
  let wanted = delivered;
  if (m[1] && m[1] !== 'all') {
    const ranks = (m[1].match(/\d/g) || []).map(Number);
    wanted = delivered.filter(d => ranks.includes(Number(d.rank)));
    if (!wanted.length) return invalid(`No delivered clip matches "${raw}" (delivered: ${delivered.map(d => '#' + d.rank).join(', ')})`);
  }
  return wanted.map((d, i) => ({ json: { ...d, action: 'upload', reply: raw, upload_index: i, upload_count: wanted.length } }));
}


if (['reject all', 'no', 'none', 'skip', 'skip all', 'reject'].includes(text)) return [{ json: { ...base, action: 'reject' } }];

// Split into picks: "1 and 5", "1, 5", "1 + 5", "1 & 5", "1 5". Adjustments stay attached to the pick they follow.
const PICK = /^(\d)(?:\s*(?:start|end)\s*([+-]?\d+(?:\.\d+)?)\s*s?\s*(earlier|later)?)*$/i;
const parts = text.split(/\s*(?:,|\band\b|\+|&)\s*|(?<=\b\d)\s+(?=\d\b)/).map(s => s.trim()).filter(Boolean);
if (!parts.length || !parts.every(pt => PICK.test(pt))) return invalid(`Could not parse reply "${raw}"`);

const out = [];
const seen = new Set();
for (const pt of parts) {
  const rank = Number(pt.match(/^(\d)/)[1]);
  if (seen.has(rank)) continue;
  seen.add(rank);
  const cand = (review.candidates || []).find(c => Number(c.rank) === rank);
  if (!cand) return invalid(`No candidate #${rank}`);
  let start = Number(cand.start), end = Number(cand.end);
  const clauseRe = /(start|end)\s*([+-]?\d+(?:\.\d+)?)\s*s?\s*(earlier|later)?/g;
  let m;
  while ((m = clauseRe.exec(pt)) !== null) {
    let delta = parseFloat(m[2]);
    if (m[3] === 'earlier') delta = -Math.abs(delta);
    else if (m[3] === 'later') delta = Math.abs(delta);
    if (m[1] === 'start') start += delta; else end += delta;   // bare signed number: + = later, - = earlier
  }
  const clamp = v => Math.min(Math.max(0, v), duration || v);
  start = clamp(start); end = clamp(end);
  if (end <= start) return invalid(`#${rank}: window collapsed (start ${start}s ≥ end ${end}s)`);
  out.push({ json: { ...base, action: 'render', rank, start: Number(start.toFixed(3)), end: Number(end.toFixed(3)),
                     duration: Number((end - start).toFixed(3)), candidate: { ...cand, start, end },
                     pick_index: out.length, pick_count: 0,
                     captions: cfg.CAPTIONS !== false, offset: cfg.RENDER_OFFSET, audio_mode: cfg.AUDIO_MODE, volume: cfg.VOLUME } });
}
for (const o of out) o.json.pick_count = out.length;
return out;

// Pair each Render result with the pick that produced it (same order; Render runs once per pick).
let picks;
try { picks = $('Auto Select').all(); if (!picks.length) throw new Error('no auto picks'); } catch (e) { picks = $('Parse Reply').all(); }
return $input.all().map((it, i) => ({ json: { ...picks[i].json, render: it.json } }));

// Pair each Package result with its pick + render result.
const picks = $('Attach Pick').all();
return $input.all().map((it, i) => ({ json: { ...picks[i].json, package: it.json } }));

// Map the preview file to its path inside the n8n container and write the Telegram caption.
const cfg = $('Config').first().json;
const out = [];
for (const it of $input.all()) {
  const j = it.json;
  const pkg = j.package || {};
  const win = pkg.preview || j.render.output;
  const root = String(cfg.CLIPS_ROOT || '').replace(/\\+$/, '');
  let cpath = null;
  if (root && win.toLowerCase().startsWith(root.toLowerCase())) {
    cpath = (cfg.CONTAINER_CLIPS || '/data/clips') + win.slice(root.length).replace(/\\/g, '/');
  }
  const p = j.candidate.predict || {};
  const mmss = s => { s = Math.max(0, Math.round(Number(s) || 0)); return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`; };
  const n = j.pick_count > 1 ? ` (${j.pick_index + 1} of ${j.pick_count})` : '';
  const caption =
    `🎬 Clip #${j.rank} ready${n} — ${j.original}\n` +
    `${mmss(j.start)} → ${mmss(j.end)} (${Math.round(j.duration)} s) · score ${p.total ?? '?'}/100 · ${j.render.encoder || 'encoded'}` +
    ((j.candidate.signals || {}).voice_command ? `\n🎤 you said "${j.candidate.signals.voice_command.text}" at ${mmss(j.candidate.signals.voice_command.at)}` : '') +
    (p.notes && p.notes.visual && p.notes.visual.penalty ? `\n⚠️ ${p.notes.visual.penalty}` : '') +
    `\nSaved: ${j.render.output}\nCapCut package: ${pkg.package_dir || '-'}` +
    (j.auto ? `\n\n⏳ Auto mode: uploading now, scheduled for ${j.publish_local || 'the next slot'} — link follows.` :
    `\n\n👉 Reply "post" to upload it to YouTube Shorts (${cfg.POST_PRIVACY || 'public'})` +
    (j.pick_count > 1 ? `, "post ${j.rank}" for just this one, "post all" for all ${j.pick_count}` : '') +
    `, or "keep" to leave it in Ready. Long-press → Reply if several are open.`);
  out.push({ json: { ...j, preview_container_path: cpath, preview_windows_path: win, caption } });
}
return out;

// Second review phase: the clips were delivered; now wait for "post" / "keep" (same poll loop, phase = post).
const cfg = $('Config').first().json;
const picks = $('Confirm Delivery').all().map(it => it.json);
const sentMsgs = picks.map(p => p.delivery_message_id).filter(Boolean);
const sent_at = Math.floor(Date.now() / 1000);
const hours = Number(cfg.REVIEW_TIMEOUT_HOURS) || 24;
return [{ json: {
  phase: 'post',
  job_id: picks[0].job_id,
  review_message_id: sentMsgs[sentMsgs.length - 1] || null,
  review_message_ids: sentMsgs,
  ranks: picks.map(p => p.rank),
  sent_at, deadline: sent_at + hours * 3600, poll_offset: 0, attempts: 0,
} }];

// Pair upload results with their clip (same order).
const picks = $('Parse Reply').all();
return $input.all().map((it, i) => ({ json: { ...picks[i].json, upload: it.json } }));

// One log record per delivered clip, with the YouTube link when it was posted.
const delivered = $('Prepare Clip Message').all().map(it => it.json);
let uploads = [];
try { uploads = $('Attach Upload').all().map(it => it.json); } catch (e) { uploads = []; }
try { if (!uploads.length) uploads = $('Attach Auto Upload').all().map(it => it.json); } catch (e) {}
const byRank = {}; for (const u of uploads) byRank[u.rank] = u.upload || {};
return delivered.map(d => ({ json: {
  job_id: d.job_id, input: d.input, candidates: d.candidates,
  approved: { rank: d.rank, start: d.start, end: d.end, reply: d.reply, pick_index: d.pick_index, pick_count: d.pick_count },
  output: d.render.output, package_dir: (d.package || {}).package_dir,
  posted: byRank[d.rank] && byRank[d.rank].url ? { url: byRank[d.rank].url, video_id: byRank[d.rank].video_id, privacy: byRank[d.rank].privacy, title: byRank[d.rank].title, publish_at: byRank[d.rank].publish_at || null } : null,
  status: byRank[d.rank] && byRank[d.rank].url ? 'posted' : 'delivered',
} }));

// One item per delivered clip. If the video message went out, keep its message_id; if Telegram refused the
// file (too big / unreadable), send the caption as a text message instead so the delivery is never silent.
const cfg = $('Config').first().json;
const prepared = $('Prepare Clip Message').all().map(it => it.json);
const out = [];
const items = $input.all();
for (let i = 0; i < prepared.length; i++) {
  const sent = (items[i] && items[i].json) || {};
  const r = sent.result || sent;
  let msgId = r && r.message_id ? r.message_id : null;
  let note = null;
  if (!msgId) {
    note = sent.error ? String(sent.error.message || sent.error).slice(0, 160) : 'preview could not be attached';
    try {
      const resp = await this.helpers.httpRequest({ method: 'POST', json: true, timeout: 20000,
        url: 'https://api.telegram.org/bot' + cfg.TELEGRAM_BOT_TOKEN + '/sendMessage',
        body: { chat_id: cfg.TELEGRAM_CHAT_ID, text: '✅ ' + prepared[i].caption + '\n(video preview not attached: ' + note + ')' } });
      msgId = resp && resp.result ? resp.result.message_id : null;
    } catch (e) { note += ' | text fallback failed: ' + String(e.message || e).slice(0, 120); }
  }
  out.push({ json: { ...prepared[i], delivery_message_id: msgId, delivery_note: note } });
}
return out;

// AUTO mode: choose the clips without a text review, in the same item shape Parse Reply produces.
//   1. every "clip it" voice command (always),
//   2. then heuristic picks with total >= AUTO_MIN_SCORE that passed the visual check,
//   up to AUTO_MAX_PER_DAY, no overlapping windows. Each pick gets a publish slot (today's remaining
//   AUTO_SLOTS in AUTO_TZ, then tomorrow's) so the Shorts go out spread through the day.
const cfg = $('Config').first().json;
const review = $('Build Review Message').first().json;
const cands = (review.candidates || []).slice();
const maxN = Number(cfg.AUTO_MAX_PER_DAY) || 4;
const minScore = Number(cfg.AUTO_MIN_SCORE) || 80;
const tz = cfg.AUTO_TZ || 'America/New_York';
// Just-ended stream (twitch_vods.py --rapid names it live_*): post the top AUTO_RAPID picks right away,
// back to back, and still schedule anything beyond that on the normal slots.
const rapid = /^live_/i.test(String(review.original || '')) ? (Number(cfg.AUTO_RAPID) || 3) : 0;

const voice = cands.filter(c => (c.signals || {}).voice_command);
const rest = cands.filter(c => !(c.signals || {}).voice_command)
  .filter(c => c.strong_moment && ((c.predict || {}).total || 0) >= minScore)
  .filter(c => !(((c.predict || {}).notes || {}).visual || {}).window_bad)
  .filter(c => !(((c.predict || {}).notes || {}).visual || {}).low_action)   // dark/idle/talk/shop screens
  .sort((a, b) => ((b.predict || {}).total || 0) - ((a.predict || {}).total || 0));
const overlaps = (a, b) => Math.max(0, Math.min(a.end, b.end) - Math.max(a.start, b.start)) / Math.max(1, Math.min(a.end - a.start, b.end - b.start)) > 0.25;
const chosen = [];
for (const c of [...voice, ...rest]) {
  if (chosen.length >= maxN) break;
  if (chosen.some(x => overlaps(x, c))) continue;
  chosen.push(c);
}
if (rapid && chosen.length < rapid) {
  // a stream always gets AUTO_RAPID posts: top up with the next-best strong moments that passed the
  // visual check, even under AUTO_MIN_SCORE (never menus/static screens)
  const extra = cands.filter(c => !chosen.includes(c) && c.strong_moment)
    .filter(c => !(((c.predict || {}).notes || {}).visual || {}).window_bad)
    // action windows first; dark/idle/talk ones only if that's all the stream has (Brian: always post 3)
    .sort((a, b) => (+!!(((a.predict || {}).notes || {}).visual || {}).low_action - +!!(((b.predict || {}).notes || {}).visual || {}).low_action)
      || (((b.predict || {}).total || 0) - ((a.predict || {}).total || 0)));
  for (const c of extra) {
    if (chosen.length >= rapid) break;
    if (chosen.some(x => overlaps(x, c))) continue;
    chosen.push(c);
  }
}
if (!chosen.length) return [{ json: { action: 'none', job_id: review.job_id, job_dir: review.job_dir, original: review.original,
  error: 'auto mode: nothing met the bar (no "clip it", nothing >= ' + minScore + '/100 that passed the visual check)' } }];

// ---- publish slots in the configured time zone
function tzOffsetMin(dateUtc) {           // minutes to ADD to local wall time to get UTC, for that instant
  const f = new Intl.DateTimeFormat('en-US', { timeZone: tz, hour12: false, year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit' });
  const p = Object.fromEntries(f.formatToParts(dateUtc).map(x => [x.type, x.value]));
  const asUtc = Date.UTC(+p.year, +p.month - 1, +p.day, +p.hour % 24, +p.minute, +p.second);
  return (dateUtc.getTime() - asUtc) / 60000;
}
function localToUtc(y, m, d, hh, mm) {
  let guess = new Date(Date.UTC(y, m, d, hh, mm));
  guess = new Date(guess.getTime() + tzOffsetMin(guess) * 60000);
  return new Date(Date.UTC(y, m, d, hh, mm) + tzOffsetMin(guess) * 60000);
}
const now = new Date();
const nowLocal = Object.fromEntries(new Intl.DateTimeFormat('en-US', { timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(now).map(x => [x.type, x.value]));
const slots = String(cfg.AUTO_SLOTS || '10:00,13:00,16:00,19:00').split(',').map(s => s.trim()).filter(Boolean);
const times = [];
const nRapid = Math.min(rapid, chosen.length);
for (let i = 0; i < nRapid; i++) times.push(null);   // null publish_at = public right now
for (let dayOff = 0; times.length < chosen.length && dayOff < 7; dayOff++) {
  for (const sl of slots) {
    const [hh, mm] = sl.split(':').map(Number);
    const t = localToUtc(+nowLocal.year, +nowLocal.month - 1, +nowLocal.day + dayOff, hh, mm);
    if (t.getTime() > now.getTime() + 20 * 60000) times.push(t);   // YouTube needs the slot in the future
    if (times.length >= chosen.length) break;
  }
}
const fmtLocal = t => new Intl.DateTimeFormat('en-US', { timeZone: tz, weekday: 'short', month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' }).format(t);

return chosen.map((cand, i) => ({ json: {
  action: 'render', reply: 'auto', auto: true,
  job_id: review.job_id, job_dir: review.job_dir, input: review.input, original: review.original, candidates: cands,
  rank: cand.rank, start: cand.start, end: cand.end, duration: Number((cand.end - cand.start).toFixed(3)), candidate: cand,
  pick_index: i, pick_count: chosen.length,
  publish_at: times[i] ? times[i].toISOString().replace(/\.\d{3}Z$/, 'Z') : null,
  publish_local: times[i] ? fmtLocal(times[i]) : (i < nRapid ? 'now (post-stream)' : null),
  captions: cfg.CAPTIONS !== false, offset: cfg.RENDER_OFFSET, audio_mode: cfg.AUDIO_MODE, volume: cfg.VOLUME,
} }));

// Pair scheduled-upload results with their clip (same order).
const picks = $('Confirm Delivery').all();
return $input.all().map((it, i) => ({ json: { ...picks[i].json, upload: it.json } }));
